def load_words(path: str | Path = DEFAULT_WORDS_PATH) -> tuple[str, ...]:
    dataset_path = Path(path)
    with dataset_path.open(encoding="utf-8") as dataset:
        words: list[str] = []
        for line in dataset:
            stripped_line = line.strip()
            if stripped_line:
                words.append(stripped_line)
    return tuple(words)
